<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import UiIcon from './UiIcon.vue'
import {credentialText} from './credential-text'
import {sourceText} from './source-text'
import SupportPage from './SupportPage.vue'
import {createApi,ApiError} from './api'
import type {Locale} from './i18n'
import {translate} from './i18n'
import {commandKey} from './deposit'
import {recoveryText,type RecoveryTextKey} from './recovery-text'
import {readRecoveryDraft,readOpenedRecovery,executeRecoveryOpen,recoveryApiPath,type RecoveryDraft} from './recovery-flow'
const props=defineProps<{service:ReturnType<typeof createApi>;locale:Locale;kind:'login'|'payment';userUid?:string;phone?:string;visitorService?:ReturnType<typeof createApi>;storage?:Pick<Storage,'getItem'|'setItem'|'removeItem'>}>()
const emit=defineEmits<{back:[];unauthorized:[];paymentSetup:[]}>()
const w=(key:RecoveryTextKey)=>recoveryText(props.locale,key)
const phone=ref(props.phone??''),busy=ref(false),error=ref<RecoveryTextKey|null>(null),draft=ref<RecoveryDraft|null>(null)
type Case={case_no:string;kind:string;status:string;version:string;created_at:string}
const record=ref<Case>(),owner=props.kind==='payment'?props.userUid??'':'guest',keyForPhone=(value:string)=>`recovery-case:login:${value}`,storageKey=()=>props.kind==='login'?keyForPhone(phone.value):`recovery-case:${props.kind}:${owner}`,guest=props.visitorService??createApi()
const store=props.storage??{getItem:(key:string)=>localStorage.getItem(key),setItem:(key:string,value:string)=>localStorage.setItem(key,value),removeItem:(key:string)=>localStorage.removeItem(key)}
let disposed=false,fullAuthFailed=false
const transport={...guest,async request<T>(path:string,body?:unknown,headers?:Record<string,string>):Promise<T>{if(path==='/support/conversation')return {conversation_id:'recovery'} as T;const value=await guest.request<T>(recoveryApiPath(path),body,headers);if(!disposed&&path.startsWith('/support/messages')&&value&&typeof value==='object'&&'case' in value)record.value=(value as {case:Case}).case;return value},image(path:string){return guest.image(recoveryApiPath(path))}}
function persist(value:RecoveryDraft){try{const raw=store.getItem(storageKey()),old=readRecoveryDraft(raw,owner,props.kind);if(raw&&(!old||old.key!==value.key))throw Error('storage');store.setItem(storageKey(),JSON.stringify(value));draft.value=value}catch{throw Error('storage')}}
async function open(){if(busy.value)return;error.value=null;if(props.kind==='login'&&draft.value&&draft.value.phone!=='+86'+phone.value){try{store.removeItem(keyForPhone(draft.value.phone.replace(/^\+86/,'')));draft.value=null;record.value=undefined;guest.setToken(null)}catch{error.value='storage';return}}if(!draft.value&&props.kind==='login'&&!/^1[3-9][0-9]{9}$/.test(phone.value)){error.value='phoneInvalid';return}busy.value=true;try{const d=draft.value??{credential:'rc1_'+commandKey()+commandKey(),key:commandKey(),kind:props.kind,phone:props.kind==='login'?'+86'+phone.value:'',owner};guest.setToken(d.credential);const opened=await executeRecoveryOpen({draft:d,persist,active:()=>!disposed,post:async()=>{try{return await (props.kind==='login'?guest.request('/recovery/cases',{kind:'login',phone:d.phone},{'Idempotency-Key':d.key}):props.service.request('/security/recovery',{kind:'payment'},{'Idempotency-Key':d.key,'X-Recovery-Credential':d.credential}))}catch(e){if(props.kind==='payment'&&e instanceof ApiError&&e.status===401)fullAuthFailed=true;throw e}}});if(disposed)return;const value=await readOpenedRecovery(opened,()=>guest.request<Case>('/recovery/case'));if(!disposed){if(value)record.value=value;else error.value='pending'}}catch(e){if(disposed)return;if(e instanceof Error&&e.message==='storage')error.value='storage';else if(e instanceof ApiError&&e.status===401){error.value='scopeExpired';if(fullAuthFailed)emit('unauthorized')}else error.value='pending'}finally{if(!disposed)busy.value=false}}
async function restore(){try{const raw=store.getItem(storageKey());draft.value=readRecoveryDraft(raw,owner,props.kind);if(raw&&!draft.value){error.value='storage';return}if(draft.value){phone.value=draft.value.phone.replace(/^\+86/,'');guest.setToken(draft.value.credential);try{const value=await guest.request<Case>('/recovery/case');if(!disposed)record.value=value}catch{if(!disposed)await open()}}else if(props.kind==='payment')await open()}catch{if(!disposed)error.value='storage'}}
function expired(){record.value=undefined;error.value='scopeExpired'}
function newCase(){if(busy.value||!window.confirm(w('newCase')+'?'))return;try{const current=readRecoveryDraft(store.getItem(storageKey()),owner,props.kind);if(current?.key!==draft.value?.key)throw Error('storage');store.removeItem(storageKey());draft.value=null;record.value=undefined;error.value=null;guest.setToken(null);if(props.kind==='payment')void open()}catch{error.value='storage'}}
onMounted(()=>restore());onUnmounted(()=>{disposed=true;guest.setToken(null)})
</script>
<template>
<SupportPage v-if="record" :service="transport" :locale="locale" recovery :case-status="record.status" @back="emit('back')" @unauthorized="expired"><template #context><div class="px-margin-sm py-space-sm"><p>{{w('caseNo')}} {{record.case_no}} · {{w(record.status as RecoveryTextKey)}}</p><p>{{w('proofHint')}}</p><div v-if="kind==='payment'&&record.status==='awaiting_user'" class="flex flex-col gap-space-sm"><p>{{w('paymentSetupHint')}}</p><button class="w-full h-12 bg-primary text-on-primary rounded-lg" style="background-color:rgb(217,119,6)" @click="emit('paymentSetup')" type="button">{{credentialText(locale,'setup')}}</button></div><button v-if="['completed','rejected','expired','superseded'].includes(record.status)" @click="newCase" type="button">{{w('newCase')}}</button></div></template></SupportPage>
<div v-else class="reference-surface reference-login"><header class="fixed top-0 w-full z-50 pt-safe bg-surface/80 backdrop-blur-xl"><div class="h-14 px-margin-sm flex items-center justify-between"><button :disabled="busy" @click="emit('back')" type="button">{{kind==='payment'?credentialText(locale,'back'):w('returnLogin')}}</button><h1 class="font-headline-sm text-headline-sm min-w-0 truncate" :title="w('title')">{{w('title')}}</h1></div></header><main class="flex flex-col relative w-full pt-14 pb-safe bg-surface min-h-screen"><div class="flex flex-col w-full px-margin-sm pb-space-xl"><form @submit.prevent="open" class="bg-surface-container-lowest rounded-xl p-space-md shadow-sm space-y-space-md"><div class="space-y-1.5" v-if="kind==='login'">
<label class="block font-label-caps text-label-caps text-outline uppercase tracking-wider" for="recovery-phone">{{translate(locale,'phone')}}</label>
<div class="flex items-center bg-surface-container-low rounded-lg px-space-sm h-12 focus-within:bg-surface-container-lowest focus-within:ring-2 focus-within:ring-primary/20 transition-all" id="wrapper-account">
<span class="flex items-center gap-0.5 text-on-surface font-label-numeric-md text-label-numeric-md pr-space-xs mr-space-xs" id="prefix-btn">+86</span>
<span class="w-[1px] h-4 bg-outline-variant mr-space-xs"></span>
<input :aria-invalid="error==='error'" :placeholder="translate(locale,'phonePlaceholder')" :readonly="busy||!!draft" autocomplete="username" class="w-full bg-transparent font-body-md text-body-md text-on-surface placeholder:text-outline-variant outline-none" id="recovery-phone" inputmode="numeric" maxlength="11" name="phone" type="tel" v-model="phone"/>
<button :aria-label="sourceText(locale,'clearAccount')" :disabled="busy||!!draft||!phone" @click="phone='';error=null" class="p-1 text-outline hover:text-on-surface flex items-center justify-center" type="button"><UiIcon :size="16" name="close"></UiIcon></button>
</div>
</div><p class="font-body-sm text-body-sm text-outline">{{w('proofHint')}}</p><p v-if="error" role="alert">{{w(error)}}</p><button :disabled="busy" class="w-full h-12 bg-primary text-on-primary rounded-lg" style="background-color:rgb(217,119,6)" type="submit">{{busy?translate(locale,'loading'):w(draft?'retry':'openCase')}}</button><button v-if="draft&&error==='scopeExpired'" @click="newCase" type="button">{{w('newCase')}}</button></form></div></main></div>
</template>
